 toIndex		'STR#', 1005, 3,			// fromType,	fromID, fromIndex				4005, 2				//				toID, toIndex	}};resource 'STR#' (4005, "Replacement Hebrew STR#")	{{	"My life is coloured pink",	"I feel somewhat shirty"	}};